// Exported model values are immutable. This module performs no online training.
function extractFeatures(samples){
 if(!Array.isArray(samples)||samples.length!==2048)throw new Error('Exactly 2048 acceleration samples are required.');
 if(samples.some(x=>typeof x!=='number'||!Number.isFinite(x)||Math.abs(x)>100))throw new Error('Samples must be finite numbers within ±100 source acceleration units.');
 const n=samples.length;let sum=0,square=0,peak=0;for(const x of samples){sum+=x;square+=x*x;peak=Math.max(peak,Math.abs(x))}const mean=sum/n,rms=Math.sqrt(square/n);let m2=0,m4=0;for(const x of samples){const d=x-mean;m2+=d*d;m4+=d**4}m2/=n;m4/=n;if(rms<1e-12||m2<1e-16)throw new Error('Flat or zero-energy signals cannot be scored.');return [rms,m4/(m2*m2),peak/rms];
}
function scoreFeatures(f,model,name=model.selected){
 if(name==='RMS threshold')return f[0];
 const z=f.map((v,i)=>(v-model.mean[i])/model.scale[i]);
 if(name==='Autoencoder'){let a=z;for(let k=0;k<model.autoencoder.weights.length;k++){const w=model.autoencoder.weights[k],b=model.autoencoder.biases[k];a=b.map((v,j)=>{let sum=v;for(let i=0;i<a.length;i++)sum+=a[i]*w[i][j];return k===model.autoencoder.weights.length-1?sum:Math.tanh(sum)})}return a.reduce((sum,v,i)=>sum+(v-z[i])**2,0)/z.length}
 if(name==='Isolation Forest'){const Z=z.map(Math.fround);let total=0;for(const tree of model.isolation_forest.trees){let node=0,depth=0;while(tree.left[node]!==-1){node=Z[tree.feature[node]]<=tree.threshold[node]?tree.left[node]:tree.right[node];depth++}total+=depth+tree.leaf_c[node]}return 2**(-total/(model.isolation_forest.trees.length*model.isolation_forest.normalizer))}
 throw new Error('Unknown model');
}
function infer(samples,model,name=model.selected){const f=extractFeatures(samples);const score=scoreFeatures(f,model,name);const threshold=model.thresholds[name];const ratio=score/threshold;const health=Math.max(0,Math.min(1,1-0.25*ratio**3));const band=health>=0.9?'healthy':health>=0.75?'watch':'inspect';return {health,band,health_scale:'Display index: clamp(1 - 0.25 × (raw score / threshold)^3, 0, 1); not a failure probability',model:name,model_version:model.version,features:Object.fromEntries(model.features.map((k,i)=>[k,f[i]])),score,threshold,ratio:score/threshold,prediction:score>=threshold?'anomaly':'normal',action:score>=threshold?'Review this window and arrange an inspection if operating context supports it.':'Continue monitoring; this score does not guarantee a healthy bearing.',scope:'CWRU benchmark; not a failure probability or live diagnosis'};}

const HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Motor Health / Final Review</title><style>\n@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;450;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');\n:root{--ink:#18201f;--muted:#68716a;--paper:#f4f4ed;--line:#d8dcd2;--green:#46684b;--amber:#ce7b27;--red:#b64b36}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:'DM Sans',Arial,sans-serif}button,a,input,select{font:inherit}button,a{touch-action:manipulation}button{cursor:pointer}button:focus-visible,a:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #ce7b27;outline-offset:4px}a{color:inherit;text-decoration:none}button{border:1px solid var(--line);background:transparent;color:inherit;padding:11px 17px;border-radius:3px}button:hover{background:#e4e8dc}button.primary{background:var(--ink);color:#f5f5ee;border-color:var(--ink)}.brand{display:flex;gap:12px;align-items:center;font-family:'Space Grotesk';font-weight:600;letter-spacing:-.6px;font-size:22px}.mark{display:grid;place-items:center;background:var(--ink);color:#e8f7b2;width:32px;height:32px;font-size:19px}.top{height:80px;display:flex;align-items:center;justify-content:space-between;padding:0 4vw;border-bottom:1px solid var(--line);gap:20px}.top nav{display:flex;gap:26px;align-items:center;font-size:13px}.top nav .active{border-bottom:2px solid var(--ink);padding:28px 0}.tag,.eyebrow{font-size:11px;letter-spacing:1.4px;text-transform:uppercase;font-weight:600}.tag{display:flex;align-items:center;gap:8px;color:var(--muted)}.dot{height:7px;width:7px;border-radius:50%;background:var(--green);display:inline-block}.page{padding:38px 4vw 30px;max-width:1700px;margin:auto}.heading{display:flex;justify-content:space-between;align-items:end;gap:25px}.eyebrow{color:var(--muted);margin-bottom:13px}h1,h2,h3,p{margin:0}h1,h2,h3{font-family:'Space Grotesk',Arial,sans-serif;font-weight:500}h1{font-size:clamp(35px,4vw,54px);letter-spacing:-2px;line-height:1.1}.heading p{margin-top:13px;color:var(--muted);font-size:14px}.actions{display:flex;gap:9px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);margin-top:35px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.metric{padding:23px 28px;border-right:1px solid var(--line)}.metric:first-child{padding-left:0}.metric:last-child{border:0}.metric label{font-size:12px;color:var(--muted)}.metric strong{display:block;font-family:'Space Grotesk';font-size:42px;letter-spacing:-2px;font-weight:500;margin:6px 0}.metric small{font-size:11px;color:var(--muted)}.workspace{display:grid;grid-template-columns:320px 1fr;gap:32px;margin-top:32px}.sectiontitle{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}h2{font-size:20px;letter-spacing:-.5px}.sectiontitle small{color:var(--muted);font-size:12px}.filters{display:flex;gap:6px;margin:0 0 15px}.filters button{font-size:11px;padding:7px 10px}.filters .selected{background:var(--ink);color:white}.search{width:100%;padding:11px 12px;border:1px solid var(--line);background:transparent;border-radius:3px;margin-bottom:10px;font-size:12px}.motor{width:100%;text-align:left;display:grid;grid-template-columns:1fr auto;padding:20px 15px;margin:0;border:0;border-bottom:1px solid var(--line);border-left:3px solid transparent;border-radius:0}.motor.selected{background:#e7ebdf;border-left-color:#50634b}.motor strong{display:block;font-size:15px;font-weight:600;margin-bottom:7px}.motor small{font-size:11px;color:var(--muted)}.state{font-size:10px;display:flex;gap:6px;align-items:center;color:var(--green);align-self:start;white-space:nowrap}.state.inspect{color:var(--amber)}.state.urgent{color:var(--red)}.state .dot{background:currentColor}.detail{border:1px solid var(--line);background:#fafaf5;padding:25px 28px}.detailhead{display:flex;align-items:center;justify-content:space-between}.detailhead h2{font-size:25px}.detailhead p{font-size:12px;color:var(--muted);margin-top:7px}.readings{display:grid;grid-template-columns:repeat(4,1fr);margin-top:28px}.reading{border-right:1px solid var(--line);padding-left:24px}.reading:first-child{padding-left:0}.reading:last-child{border:0}.reading label{font-size:11px;color:var(--muted)}.reading strong{display:block;font-size:27px;font-family:'Space Grotesk';font-weight:500;margin-top:7px}.reading strong small{font-size:12px;color:var(--muted)}.charthead{margin-top:30px;display:flex;justify-content:space-between;font-size:12px}.charthead span{color:var(--muted)}.chart{height:185px;margin-top:10px;position:relative}svg{width:100%;height:100%;overflow:visible}.chartpath{stroke-dasharray:1600;stroke-dashoffset:1600;animation:draw 1.5s ease forwards}.axis{display:flex;justify-content:space-between;font-size:10px;color:var(--muted);padding-left:30px}.lower{display:grid;grid-template-columns:1.2fr 1fr;gap:24px;margin-top:25px;padding-top:22px;border-top:1px solid var(--line)}.lower p{font-size:12px;line-height:1.7;color:var(--muted);margin-top:9px}.lower h3{font-size:16px}.scorebar{height:5px;background:#e0e4da;margin:13px 0}.scorebar i{display:block;height:100%;transition:width .6s}.scenario{margin-top:20px;border-top:1px solid var(--line);padding-top:16px;display:flex;justify-content:space-between;align-items:center;gap:12px}.scenario label{font-size:11px;color:var(--muted)}select{background:transparent;border:1px solid var(--line);padding:7px;font-size:12px;color:var(--ink)}.foot{display:flex;justify-content:space-between;gap:20px;border-top:1px solid var(--line);margin-top:30px;padding-top:17px;font-size:10px;color:var(--muted);line-height:1.7}.demo-note{background:#e9ecdf;padding:12px 15px;margin-top:16px;font-size:11px;color:#58614f;line-height:1.6}.toast{position:fixed;bottom:30px;left:50%;transform:translateX(-50%);padding:15px 24px;background:var(--ink);color:white;font-size:13px;z-index:50;box-shadow:0 8px 30px #0002}.empty{padding:30px 0;color:var(--muted);font-size:13px}.error{padding:25px;color:var(--red)}\n/* Presentation: generous editorial layouts and paced reveals. */\n#presentation{display:none;position:fixed;inset:0;z-index:20;background:#eff0e8}.present-top{height:68px;border-bottom:1px solid #ccd1c3;display:flex;justify-content:space-between;align-items:center;padding:0 4vw;font-size:11px;letter-spacing:1px}.present-top button{padding:8px 12px;letter-spacing:0;font-size:12px}.slide{height:calc(100dvh - 136px);padding:5vh 7vw;overflow:auto;position:relative}.slide .eyebrow{color:#65705e}.slide h1{font-size:clamp(32px,4.3vw,65px);max-width:1120px;white-space:pre-line;line-height:1.07}.slide .subtitle{font-size:clamp(15px,1.45vw,22px);color:#60695c;line-height:1.5;margin-top:22px;max-width:1010px}.slide-items{display:grid;grid-template-columns:repeat(3,1fr);gap:40px;margin-top:7vh}.slide-item{border-top:1px solid #b9c2ae;padding-top:20px}.slide-item h3{font-size:clamp(18px,1.7vw,27px);margin-bottom:15px}.slide-item p{font-size:clamp(14px,1.35vw,20px);line-height:1.55;color:#626a5e}.slide-note{position:absolute;bottom:3vh;left:7vw;right:7vw;font-size:12px;color:#65705e;line-height:1.5}.slide.cover{background:#19231f;color:#f1f3e7}.slide.cover .eyebrow,.slide.cover .subtitle,.slide.cover .slide-note,.slide.cover p{color:#bdc9b4}.slide.cover h1{font-size:clamp(50px,7vw,105px);max-width:1100px;letter-spacing:-4px}.slide.cover .slide-items{max-width:900px;margin-top:5vh}.slide.cover .slide-item{border-color:#4c5a48}.slide.metrics .slide-items,.slide.steps .slide-items{grid-template-columns:repeat(3,1fr);gap:26px;margin-top:4vh}.slide.metrics{display:block;margin:0;border:0}.slide.metrics .slide-item h3{font-size:44px;color:#506d3e}.slide.steps .slide-item h3{font-size:21px}.slide.steps .slide-item p{font-size:17px}.slide.metrics .slide-item p{font-size:16px}.present-bottom{height:68px;display:flex;justify-content:space-between;align-items:center;padding:0 4vw;border-top:1px solid #ccd1c3;font-size:12px}.present-bottom .buttons{display:flex;gap:8px}.progress{height:3px;background:#506d3e;position:absolute;bottom:0;left:0;transition:width .4s}.slide >*{animation:rise .65s both}.slide .subtitle{animation-delay:.09s}.slide .slide-item{animation:rise .65s both;animation-delay:calc(.14s + var(--i)*.10s)}.slide .slide-note{animation-delay:.5s}.speaker{display:none;position:absolute;bottom:70px;right:3vw;width:min(570px,90vw);padding:24px;background:#fffdf3;box-shadow:0 8px 40px #0003;border:1px solid #c3c9b8;z-index:30;font-size:14px;line-height:1.7}.overview{display:none;position:absolute;inset:68px 0;background:#edf0e5;z-index:25;padding:30px 5vw;overflow:auto;grid-template-columns:repeat(3,1fr);gap:15px}.overview button{text-align:left;padding:20px}.overview small{display:block;color:var(--muted);margin-bottom:8px}.shortcut{font-size:11px;color:var(--muted)}@keyframes rise{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}}@keyframes draw{to{stroke-dashoffset:0}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}.chartpath{stroke-dashoffset:0}}\n@media(max-width:900px){.workspace{grid-template-columns:240px 1fr;gap:18px}.top nav .optional{display:none}.detail{padding:20px}.readings{grid-template-columns:repeat(2,1fr);gap:20px}.reading:nth-child(3){padding-left:0}.reading:nth-child(2){border:0}.lower{grid-template-columns:1fr}.slide-note{position:static;margin-top:35px}.slide-items{gap:22px}.slide.cover h1{letter-spacing:-2px}}@media(max-width:650px){.top{height:65px}.top nav{gap:12px}.top nav .active,.top .tag{display:none}.brand{font-size:18px}.page{padding-top:28px}.heading{align-items:start;flex-direction:column}.heading .actions{width:100%}.metrics{grid-template-columns:repeat(2,1fr);margin-top:25px}.metric{padding:18px!important}.metric:nth-child(2){border:0}.metric strong{font-size:33px}.workspace{grid-template-columns:1fr}.fleet{display:grid;grid-template-columns:1fr 1fr}.motor{padding:16px 10px}.motor strong{font-size:12px}.state{font-size:9px}.foot{flex-direction:column}.slide{padding:4vh 6vw}.slide-items,.slide.steps .slide-items,.slide.metrics .slide-items{grid-template-columns:1fr;gap:18px;margin-top:25px}.slide-item{padding-top:12px}.slide-item h3{margin-bottom:6px}.slide.cover h1{font-size:51px}.slide.cover .slide-items{grid-template-columns:1fr}.slide.cover .slide-item{padding:6px 0}.slide.cover .slide-item h3{font-size:17px}.slide.cover .slide-item p{font-size:12px}.slide.metrics .slide-item h3{font-size:30px}.present-bottom{padding:0 15px}.shortcut{display:none}.overview{grid-template-columns:1fr}.present-top{font-size:9px}.scenario{align-items:start;flex-direction:column}}\n\n.live-flag{display:inline-flex;align-items:center;gap:7px;color:#436440;font-size:11px;font-weight:700;letter-spacing:.07em;text-transform:uppercase}.live-flag i{width:7px;height:7px;border-radius:50%;background:#5e9d50;box-shadow:0 0 0 4px #dbe8d3}.dataset-note{font-size:11px;color:#667161;line-height:1.6;padding:13px 0;border-top:1px solid var(--line)}.health-big{font-size:38px!important}.feature-row{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:15px 0}.feature-row>div{border-top:1px solid var(--line);padding-top:9px;font-size:11px;color:var(--muted)}.feature-row strong{display:block;color:var(--ink);font-size:16px;margin-top:4px}.live-control{display:flex;align-items:center;justify-content:space-between;gap:12px;padding-top:15px;border-top:1px solid var(--line);margin-top:18px}.status-chip{font-size:11px;padding:7px 10px;border:1px solid var(--line);color:#63715c}.chart svg{width:100%;height:100%}.explain{font-size:12px;line-height:1.65;color:#60705f;margin-top:10px}.record-small{font-size:11px;color:#7a8576}.state.healthy{color:var(--green)}.state.watch{color:var(--amber)}.state.inspect{color:var(--red)}.state .dot{background:currentColor}.replay-progress{height:3px;background:#e0e5d9;margin-top:12px}.replay-progress i{display:block;height:100%;background:#78974f;transition:width .3s}.detail summary{cursor:pointer;font-size:12px;font-weight:600;color:#3d513b}@media(max-width:700px){.feature-row{grid-template-columns:1fr 1fr}.top{height:auto;padding-top:18px;padding-bottom:18px}.heading{align-items:start;flex-direction:column}}</style></head><body>\n<header class=\"top\"><a href=\"#\" class=\"brand\"><span class=\"mark\">m</span>motor health<span style=\"color:#7b8576;font-weight:400\">/</span></a><nav><a href=\"#\" class=\"active\">Fleet overview</a><a href=\"#presentation\" onclick=\"openDeck()\">Final presentation \u2197</a><a href=\"/api/report\" target=\"_blank\" class=\"optional\">Evaluation report \u2197</a></nav><span class=\"live-flag\"><i></i> Recording playback</span></header>\n<main class=\"page\"><div class=\"heading\"><div><div class=\"eyebrow\">Condition monitoring / End-term showcase</div><h1>Every signal. A clearer picture.</h1><p>Watch recorded vibration windows update, then review the bearing condition.</p></div><div class=\"actions\"><button onclick=\"exportCSV()\">Export readings \u2193</button><button class=\"primary\" onclick=\"openDeck()\">Present project \u2197</button></div></div>\n<div class=\"metrics\"><div class=\"metric\"><label>CWRU recordings</label><strong id=\"total\">08</strong><small>Drive-end vibration / 48 kHz</small></div><div class=\"metric\"><label>Healthy index</label><strong id=\"normal\">\u2014</strong><small>Health \u2265 0.90</small></div><div class=\"metric\"><label>Watch</label><strong id=\"watch\" style=\"color:var(--amber)\">\u2014</strong><small>0.75\u20130.90</small></div><div class=\"metric\"><label>Inspect</label><strong id=\"inspect\" style=\"color:var(--red)\">\u2014</strong><small>Health &lt; 0.75</small></div></div>\n<div class=\"workspace\"><aside><div class=\"sectiontitle\"><h2>Recording fleet</h2><small id=\"fleetCount\"></small></div><input class=\"search\" id=\"search\" placeholder=\"Search recording or load\" aria-label=\"Search recordings\" oninput=\"renderFleet()\"><div class=\"filters\" role=\"group\" aria-label=\"Filter condition\"><button class=\"selected\" data-filter=\"all\" onclick=\"filterFleet('all')\">All</button><button data-filter=\"attention\" onclick=\"filterFleet('attention')\">Needs attention</button></div><div class=\"fleet\" id=\"fleet\"></div><div class=\"dataset-note\"><strong>Dataset / CWRU Bearing Data Center</strong><br>Official 48 kHz drive-end vibration recordings. The eight displayed recordings were held out from training. HP means horsepower: the load applied to the test rig (2 or 3 HP here). Names identify test recordings, not installed plant assets.</div></aside><section class=\"detail\" id=\"detail\"><p>Loading recordings\u2026</p></section></div>\n<footer class=\"foot\"><span>ATLAS / uGDX \u00b7 BTECH CAP 501 \u00b7 Voyagers<br>Taher Sohagpurwala \u00b7 Harsh Agrawal \u00b7 Manthan Kumar</span><span>CWRU bearing data \u00b7 Deployed inference API \u00b7 Recording playback<br>No physical motor sensor connected</span></footer></main>\n<div id=\"presentation\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Final project presentation\"><div class=\"present-top\"><span>MOTOR HEALTH / FINAL PROJECT REVIEW</span><div><button onclick=\"toggleOverview()\">Slides</button> <button onclick=\"fullScreen()\" aria-label=\"Toggle fullscreen\">\u26f6</button> <button onclick=\"closeDeck()\">Exit \u00d7</button></div></div><article class=\"slide\" id=\"slide\"></article><div class=\"overview\" id=\"overview\"></div><div class=\"present-bottom\"><span id=\"pageNumber\"></span><span class=\"shortcut\">\u2190 \u2192 Navigate &nbsp; F Fullscreen &nbsp; Esc Exit</span><div class=\"buttons\"><button id=\"prev\" onclick=\"move(-1)\">\u2190 Previous</button><button id=\"next\" class=\"primary\" onclick=\"move(1)\">Next \u2192</button></div></div><div class=\"progress\"><i id=\"progress\"></i></div></div><div id=\"toast\" hidden></div>\n<script>\nlet records=[],slides=[],selected=null,filter='all',slideIndex=0,deckOpen=false,running=true,timer=null,history=[],windowIndex=0,requestId=0;const $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nasync function api(path){const r=await fetch(path);const x=await r.json();if(!r.ok)throw Error(x.error||'API error');return x}\nfunction statusName(x){return x==='healthy'?'Healthy':x==='watch'?'Watch':'Inspect'}function color(x){return x==='healthy'?'#46684b':x==='watch'?'#ce7b27':'#b64b36'}\nfunction label(r){return r.name.startsWith('Normal')?'Healthy bearing':r.name.startsWith('IR')?'Inner-race fault':r.name.startsWith('OR')?'Outer-race fault':'Ball fault'}\nasync function init(){try{[records,slides]=await Promise.all([api('/api/samples'),api('/api/slides')]);selected=records[0].id;await Promise.all(records.map(async r=>{const x=await api('/api/replay?recording='+r.id+'&window=0');r.current=x}));renderMetrics();renderFleet();renderDetail();tick();if(location.hash==='#presentation')openDeck()}catch(e){$('detail').innerHTML='<div class=\"error\">'+esc(e.message)+'</div>'}}\nfunction renderMetrics(){$('total').textContent=String(records.length).padStart(2,'0');for(const [id,band] of [['normal','healthy'],['watch','watch'],['inspect','inspect']])$(id).textContent=String(records.filter(r=>r.current?.band===band).length).padStart(2,'0')}\nfunction filterFleet(f){filter=f;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===f));renderFleet()}\nfunction renderFleet(){const q=$('search').value.toLowerCase();const visible=records.filter(r=>(filter==='all'||r.current?.band!=='healthy')&&(r.name+' '+r.load_hp+' '+label(r)).toLowerCase().includes(q));$('fleetCount').textContent=visible.length+' recordings';$('fleet').innerHTML=visible.map(r=>`<button class=\"motor ${r.id===selected?'selected':''}\" aria-pressed=\"${r.id===selected}\" onclick=\"selectRecord('${r.id}')\"><span><strong>${esc(r.name)}</strong><small>${label(r)} \u00b7 ${r.load_hp} HP load</small></span><span class=\"state ${r.current?.band||'healthy'}\"><i class=\"dot\"></i>${r.current?statusName(r.current.band):'Loading'}</span></button>`).join('')||'<div class=\"empty\">No recordings match.</div>'}\nfunction selectRecord(id){selected=id;windowIndex=0;history=[];requestId++;renderFleet();renderDetail();if(running)tick()}\nfunction chart(values){if(!values.length)return '';const pts=values.map((v,i)=>[20+i*650/Math.max(1,values.length-1),155-v*130]);return `<svg viewBox=\"0 0 700 180\" role=\"img\" aria-label=\"Health index over recent recorded windows\"><line x1=\"20\" x2=\"680\" y1=\"38\" y2=\"38\" stroke=\"#d3e1c6\" stroke-dasharray=\"4 5\"/><line x1=\"20\" x2=\"680\" y1=\"58\" y2=\"58\" stroke=\"#ead7b0\" stroke-dasharray=\"4 5\"/><path class=\"chartpath\" d=\"M${pts.map(p=>p.join(',')).join(' L')}\" fill=\"none\" stroke=\"#5c7d40\" stroke-width=\"3\"/><circle cx=\"${pts.at(-1)[0]}\" cy=\"${pts.at(-1)[1]}\" r=\"5\" fill=\"#5c7d40\"/></svg>`}\nfunction renderDetail(){const r=records.find(r=>r.id===selected);if(!r||!r.current)return;const x=r.current,c=color(x.band),f=x.features;const advice=x.band==='healthy'?'Continue monitoring under comparable load.':x.band==='watch'?'Review the trend and operating context.':'Arrange a bearing inspection; an engineer makes the maintenance decision.';$('detail').innerHTML=`<div class=\"detailhead\"><div><div class=\"eyebrow\">CWRU recording / ${r.load_hp} HP load</div><h2>${esc(r.name)} \u00b7 ${label(r)}</h2><p>48 kHz drive-end acceleration \u00b7 0.007-inch seeded bearing condition</p></div><span class=\"state ${x.band}\"><i class=\"dot\"></i>${statusName(x.band)}</span></div><div class=\"readings\"><div class=\"reading\"><label>Health index</label><strong class=\"health-big\" style=\"color:${c}\">${x.health.toFixed(2)} <small>/ 1.00</small></strong></div><div class=\"reading\"><label>Vibration RMS</label><strong>${f.rms.toFixed(4)}</strong></div><div class=\"reading\"><label>Kurtosis</label><strong>${f.kurtosis.toFixed(2)}</strong></div><div class=\"reading\"><label>Crest factor</label><strong>${f.crest_factor.toFixed(2)}</strong></div></div><div class=\"charthead\"><strong>Health trend <span> / scored recorded windows</span></strong><span>Window ${x.window+1} / ${x.window_count}</span></div><div class=\"chart\">${chart(history)}</div><div class=\"axis\"><span>Earlier</span><span>Health index / 0\u20131</span><span>Latest</span></div><div class=\"replay-progress\"><i style=\"width:${(x.window+1)/x.window_count*100}%\"></i></div><div class=\"lower\"><div><h3>${statusName(x.band)} \u00b7 ${advice}</h3><p>The model scores each recorded window. Green \u2265 0.90; watch 0.75\u20130.90; inspect below 0.75. The index is not a failure probability.</p></div><div><h3>Recording playback</h3><p>Backend scoring advances about once per second through this CWRU recording. This is laboratory data, not a live motor connection.</p><button id=\"playButton\" style=\"margin-top:13px\" onclick=\"togglePlayback()\">${running?'Pause':'Resume'} playback</button></div></div><details style=\"margin-top:22px;border-top:1px solid var(--line);padding-top:16px\"><summary>Model details</summary><p class=\"explain\">Selected model: ${esc(x.model)} \u00b7 Raw anomaly score: ${x.score.toPrecision(6)} \u00b7 Validation threshold: ${x.threshold.toPrecision(6)}. The health index maps score \u00f7 threshold onto 0\u20131. HP is the test rig load in horsepower, not the motor's health.</p></details>`}\nasync function tick(){clearTimeout(timer);if(!running)return;const id=selected,idx=windowIndex,seq=++requestId;try{const x=await api('/api/replay?recording='+id+'&window='+idx);if(seq!==requestId||id!==selected||!running)return;const r=records.find(r=>r.id===id);r.current=x;history.push(x.health);if(history.length>36)history.shift();windowIndex=(idx+1)%x.window_count;renderMetrics();renderFleet();renderDetail()}catch(e){running=false;toast(e.message);renderDetail();return}timer=setTimeout(tick,950)}\nfunction togglePlayback(){running=!running;if(running)tick();else{clearTimeout(timer);renderDetail()}}\nfunction exportCSV(){const rows=['recording,load_hp,window,health,band,rms,kurtosis,crest_factor,raw_score',...records.filter(r=>r.current).map(r=>[r.name,r.load_hp,r.current.window,r.current.health,r.current.band,r.current.features.rms,r.current.features.kurtosis,r.current.features.crest_factor,r.current.score].join(','))];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.join('\\n')],{type:'text/csv'}));a.download='cwru-current-readings.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}\nfunction toast(t){$('toast').textContent=t;$('toast').hidden=false;$('toast').className='toast';setTimeout(()=>$('toast').hidden=true,3500)}\nfunction openDeck(){if(!slides.length)return;deckOpen=true;$('presentation').style.display='block';document.body.style.overflow='hidden';location.hash='presentation';renderSlide()}\nfunction closeDeck(){deckOpen=false;$('presentation').style.display='none';document.body.style.overflow='';window.history.replaceState(null,'',location.pathname);if(document.fullscreenElement)document.exitFullscreen()}\nfunction renderSlide(){const s=slides[slideIndex];$('slide').className='slide '+s.type;$('slide').innerHTML=`<div class=\"eyebrow\">${esc(s.k)}</div><h1>${esc(s.title)}</h1><p class=\"subtitle\">${esc(s.sub)}</p><div class=\"slide-items\">${s.items.map((p,i)=>`<div class=\"slide-item\" style=\"--i:${i}\"><h3>${esc(p[0])}</h3><p>${esc(p[1])}</p></div>`).join('')}</div>`;$('pageNumber').textContent=String(slideIndex+1).padStart(2,'0')+' / '+slides.length;$('progress').style.width=((slideIndex+1)/slides.length*100)+'%';$('prev').disabled=slideIndex===0;$('next').disabled=slideIndex===slides.length-1}\nfunction move(d){slideIndex=Math.max(0,Math.min(slides.length-1,slideIndex+d));renderSlide()}function toggleOverview(){const el=$('overview');if(el.style.display==='grid'){el.style.display='none';return}el.innerHTML=slides.map((s,i)=>`<button onclick=\"slideIndex=${i};renderSlide();toggleOverview()\"><small>${String(i+1).padStart(2,'0')}</small>${esc(s.title)}</button>`).join('');el.style.display='grid'}function fullScreen(){if(document.fullscreenElement)document.exitFullscreen();else $('presentation').requestFullscreen?.()}\ndocument.addEventListener('keydown',e=>{if(!deckOpen)return;if(e.key==='ArrowRight'||e.key===' '){e.preventDefault();move(1)}if(e.key==='ArrowLeft'){e.preventDefault();move(-1)}if(e.key==='Escape')closeDeck();if(e.key.toLowerCase()==='f')fullScreen()});init();\n</script></body></html>";
